use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    if cs.len() == 0 {
        return false
    }
    let mut digits: int = 0
    let mut first = true
    for c in cs {
        if first && c == '-' {
            first = false
            continue
        }
        first = false
        if c < '0' || c > '9' {
            return false
        }
        digits += 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split_whitespace() {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b: int = st[st.len() - 1]
            let a: int = st[st.len() - 2]
            st.pop()
            st.pop()
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            st.push(v)
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

