use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n = cs.len()
    if n == 0 {
        return false
    }
    let start = if cs[0] == '-' { 1 } else { 0 }
    if start == n {
        return false
    }
    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' {
            return false
        }
        i += 1
    }
    true
}

